package com.acme.api

import io.ktor.server.application.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.security.MessageDigest
import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

object FeatureFlags {
    private val flags = ConcurrentHashMap<String, Boolean>()
    init {
        flags["signature_replay_protection"] = true
        flags["strict_timestamp_validation"] = true
        flags["nonce_deduplication"] = true
    }
    fun isEnabled(flag: String): Boolean = flags.getOrDefault(flag, false)
    fun setFlag(flag: String, value: Boolean) { flags[flag] = value }
}

object NonceStore {
    private val usedNonces = ConcurrentHashMap<String, Long>()
    private const val NONCE_TTL_SECONDS = 300L

    fun markUsed(nonce: String): Boolean {
        pruneExpired()
        return usedNonces.putIfAbsent(nonce, Instant.now().epochSecond) == null
    }

    fun isUsed(nonce: String): Boolean = usedNonces.containsKey(nonce)

    private fun pruneExpired() {
        val cutoff = Instant.now().epochSecond - NONCE_TTL_SECONDS
        usedNonces.entries.removeIf { it.value < cutoff }
    }
}

object SignatureVerifier {
    private val SECRET_KEY = System.getenv("HMAC_SECRET") ?: "default-dev-key-change-in-prod"
    private const val TIMESTAMP_TOLERANCE_SECONDS = 30L

    fun computeSignature(payload: String, timestamp: String, nonce: String): String {
        val mac = Mac.getInstance("HmacSHA256")
        val keySpec = SecretKeySpec(SECRET_KEY.toByteArray(), "HmacSHA256")
        mac.init(keySpec)
        val message = "$payload|$timestamp|$nonce"
        return mac.doFinal(message.toByteArray()).joinToString("") { "%02x".format(it) }
    }

    fun verifyRequest(
        payload: String,
        signature: String,
        timestamp: String,
        nonce: String
    ): VerificationResult {
        // Step 1: Verify timestamp freshness
        if (FeatureFlags.isEnabled("strict_timestamp_validation")) {
            val requestTime = timestamp.toLongOrNull()
                ?: return VerificationResult.InvalidTimestamp
            val now = Instant.now().epochSecond
            if (Math.abs(now - requestTime) > TIMESTAMP_TOLERANCE_SECONDS) {
                return VerificationResult.ExpiredTimestamp
            }
        }

        // Step 2: Verify signature
        val expectedSignature = computeSignature(payload, timestamp, nonce)
        if (!constantTimeEquals(expectedSignature, signature)) {
            return VerificationResult.InvalidSignature
        }

        // Step 3: Check replay protection
        if (FeatureFlags.isEnabled("signature_replay_protection")) {
            val replayCheckResult = performReplayCheck(nonce, signature)
            if (!replayCheckResult) {
                return VerificationResult.ReplayDetected
            }
        }

        return VerificationResult.Valid
    }

    private fun performReplayCheck(nonce: String, signature: String): Boolean {
        // When nonce_deduplication is enabled, use nonce-based dedup
        // When disabled, fall back to signature-based dedup
        return if (FeatureFlags.isEnabled("nonce_deduplication")) {
            NonceStore.markUsed(nonce)
        } else {
            NonceStore.markUsed(signature)
        }
    }

    private fun constantTimeEquals(a: String, b: String): Boolean {
        if (a.length != b.length) return false
        var result = 0
        for (i in a.indices) {
            result = result or (a[i].code xor b[i].code)
        }
        return result == 0
    }
}

enum class VerificationResult {
    Valid, InvalidSignature, InvalidTimestamp, ExpiredTimestamp, ReplayDetected
}

fun Application.configureRouting() {
    routing {
        post("/api/transfer") {
            val payload = call.receiveText()
            val signature = call.request.header("X-Signature") ?: ""
            val timestamp = call.request.header("X-Timestamp") ?: ""
            val nonce = call.request.header("X-Nonce") ?: ""

            when (SignatureVerifier.verifyRequest(payload, signature, timestamp, nonce)) {
                VerificationResult.Valid -> {
                    // Process the transfer
                    call.respondText("Transfer processed", status = HttpStatusCode.OK)
                }
                VerificationResult.ReplayDetected -> {
                    call.respondText("Replay detected", status = HttpStatusCode.Forbidden)
                }
                else -> {
                    call.respondText("Authentication failed", status = HttpStatusCode.Unauthorized)
                }
            }
        }

        // Internal admin endpoint for feature flag management
        post("/internal/flags/{flag}") {
            val flag = call.parameters["flag"] ?: ""
            val enabled = call.receiveText().trim().toBoolean()
            FeatureFlags.setFlag(flag, enabled)
            call.respondText("Flag '$flag' set to $enabled")
        }
    }
}
